const APP_VERSION='1.1.0';
const money=(n:any)=>new Intl.NumberFormat('en-GH',{style:'currency',currency:'GHS'}).format(Number(n)||0);
const today=()=>new Date().toISOString().slice(0,10);
const fmt=(v:any)=>{if(!v)return '—';const d=v instanceof Date?v:new Date(`${String(v).slice(0,10)}T00:00:00`);return Number.isNaN(d.getTime())?'—':d.toLocaleDateString('en-GH',{day:'2-digit',month:'short',year:'numeric'})};
